const drawThread=keep=>{const st=thread.scrollTop;const cur=convs.find(x=>x.id===active),dbf=cur&&cur.deletedBefore&&cur.deletedBefore[u.uid];const vis=msgs.filter(m=>!(m.hiddenFor||[]).includes(u.uid)&&(!dbf||!m.createdAt||m.createdAt.seconds>dbf.seconds));thread.innerHTML=vis.length?vis.map(m=>{const mine=m.senderId===u.uid,t=m.createdAt?.seconds?new Date(m.createdAt.seconds*1000).toLocaleTimeString('en-NG',{hour:'2-digit',minute:'2-digit'}):'',isOffer=m.type==='offer'&&offers[m.offerId]&&!m.deleted;let body,acts='';if(m.deleted)body='<div class="bubble deleted">🚫 This message was deleted</div>';else if(isOffer)body=offerCard(offers[m.offerId]);else body=`<div class="bubble">${esc(m.text)}</div>`;if(!isOffer){if(mine&&!m.deleted&&m.type!=='offer'){if(m.createdAt?.seconds&&Date.now()/1000-m.createdAt.seconds<900)acts+=`<button type="button" data-act="edit" data-mid="${m.id}">Edit</button>`;acts+=`<button type="button" data-act="delall" data-mid="${m.id}">Delete for everyone</button>`}acts+=`<button type="button" data-act="delme" data-mid="${m.id}">Delete for me</button>`}return `<div class="msg ${mine?'me':'them'}${openId===m.id?' open':''}" data-mid="${m.id}">${body}${acts?`<div class="msg-actions">${acts}</div>`:''}<span class="msg-time">${t}${m.edited&&!m.deleted?' · edited':''}</span></div>`}).join(''):'<div class="empty-state">Say hello 👋</div>';if(keep)thread.scrollTop=st;else thread.scrollTop=thread.scrollHeight};
