ob.addEventListener('click',()=>{if(!active)return;const c=convs.find(x=>x.id===active),buyer=c?other(c):null;if(!buyer||!buyer.id)return;const pubs=myProducts.filter(p=>p.status==='published');if(!pubs.length){toast('Publish a product first.',true);return}const ov=document.createElement('div');ov.className='modal-overlay';ov.innerHTML=`<div class="modal-box"><h3>Make a special offer</h3><p class="muted">Only ${esc(buyer.name)} can use this offer, one time.</p><div class="field"><label>Product</label><select id="ofProduct">${pubs.map(p=>`<option value="${p.id}">${esc(p.name)} — ${money(p.price)} (${Number(p.stock||0)} in stock)</option>`).join('')}</select></div><div class="grid grid-3"><div class="field"><label>Quantity</label><input id="ofQty" type="number" min="1" step="1" value="1"></div><div class="field"><label>Price per item (₦)</label><input id="ofPrice" type="number" min="0" step="1"></div><div class="field"><label>Valid for</label><select id="ofHours"><option value="24">24 hours</option><option value="48" selected>48 hours</option><option value="72">3 days</option><option value="168">7 days</option></select></div></div><p id="ofSummary" class="offer-summary"></p><div class="inline-actions"><button class="btn btn-primary" id="ofSend" type="button">Send offer</button><button class="btn btn-light" id="ofCancel" type="button">Cancel</button></div></div>`;document.body.appendChild(ov);const g=q=>ov.querySelector(q),prod=()=>pubs.find(p=>p.id===g('#ofProduct').value);const sync=()=>{const p=prod(),q=Math.max(1,parseInt(g('#ofQty').value)||1),pr=Number(g('#ofPrice').value)||0;g('#ofSummary').innerHTML=`Normal total ${money(Number(p.price)*q)} → <b>Offer total ${money(pr*q)}</b> (discount ${money(Math.max(0,Number(p.price)*q-pr*q))})`};g('#ofProduct').addEventListener('change',()=>{g('#ofPrice').value=prod().price;sync()});['#ofQty','#ofPrice'].forEach(q=>g(q).addEventListener('input',sync));g('#ofPrice').value=prod().price;sync();g('#ofCancel').onclick=()=>ov.remove();ov.addEventListener('click',ev=>{if(ev.target===ov)ov.remove()});g('#ofSend').onclick=async()=>{const p=prod(),q=parseInt(g('#ofQty').value),pr=Number(g('#ofPrice').value),h=Number(g('#ofHours').value);if(!(q>=1)){toast('Enter a valid quantity.',true);return}if(q>Number(p.stock||0)){toast('You only have '+Number(p.stock||0)+' in stock.',true);return}if(!(pr>=0)||pr>Number(p.price)){toast('The offer price cannot be higher than the normal price ('+money(p.price)+').',true);return}const b=g('#ofSend');b.disabled=true;try{const ref=await db.collection('offers').add({sellerId:u.uid,buyerId:buyer.id,participantIds:[u.uid,buyer.id],productId:p.id,productName:p.name,productImage:safeUrl(p.images?.[0]),qty:q,unitPrice:pr,originalPrice:Number(p.price),conversationId:active,status:'open',expiresAt:Date.now()+h*3600000,createdAt:SV()});const cr=db.collection('conversations').doc(active),text='Special offer: '+q+' × '+p.name+' at '+money(pr)+' each';await cr.collection('messages').add({senderId:u.uid,type:'offer',offerId:ref.id,text,createdAt:SV()});await cr.set({lastMessage:text.slice(0,200),updatedAt:SV()},{merge:true});ov.remove();toast('Offer sent.')}catch(err){console.error('[ShopWave] offer',err);toast((err.code||'')+' '+(err.message||'Could not send the offer.'),true);b.disabled=false}}});
